package main
import ("log";"net/http";"os")
func main(){p:=os.Getenv("PORT");if p==""{p="10000"};http.HandleFunc("/",func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","text/html; charset=utf-8");w.Write([]byte(html))});log.Println(p);http.ListenAndServe(":"+p,nil)}
const html=
"<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width'><title>U</title><script src='https://unpkg.com/xlsx@0.18.5/dist/xlsx.full.min.js'></script><style>body{margin:0;font-family:system-ui;background:#f1f5f1}header{background:#1a6d2f;color:#fff;padding:10px;text-align:center;font-weight:900}.card{background:#fff;margin:6px;border-radius:6px;padding:6px}.top3{display:flex;gap:3px}.top3 div{flex:1;padding:6px;border-radius:4px;color:#fff;text-align:center;font-weight:900;font-size:11px}.g{background:#2e7d32}.r{background:#c62828}.b{background:#1565c0}select,input,button{width:100%;padding:6px;margin:2px 0;border:1px solid #bbb}button{background:#1a6d2f;color:#fff;border:0}</style><header>Uwashusema Mahida</header><div class=card><div style='display:flex;gap:3px'><select id=m><option value=11>Nov<option value=12>Des</select><input id=y type=number value=2026><button onclick=R() style='width:50px'>Sawa</button></div><div class=top3 style='margin-top:4px'><div class=g>MAPATO<br><span id=a>0</span></div><div class=r>MATUMIZI<br><span id=b>0</span></div><div class=b>SALIO<br><span id=c>0</span></div></div></div><div class=card><b>Wanachama <button onclick=W() style='width:auto;float:right'>+ Mpya</button></b><div id=wl></div></div><div class=card><select id=sw></select><select id=sa><option value=hisa>Hisa<option value=ada>Ada<option value=marejesho>Marejesho<option value=faini_ada>Riba Ada<option value=faini_marejesho>Riba Rejesho<option value=michango>Michango<option value=mkopo_toka>Mkopo</select><input id=kv type=number placeholder=Kiasi><button onclick=M()>Hifadhi</button><div id=ca style=color:green;font-weight:900></div></div><div class=card><button onclick=E() style='background:#1565c0'>Pakua Excel</button></div><script>D=JSON.parse(localStorage.getItem('v4')||'null')||{w:[],m:[]};function S(){localStorage.setItem('v4',JSON.stringify(D));R()}function W(){j=prompt('Jina:');if(j){D.w.push({j:j});S()}}function M(){w=sw.value;a=sa.value;k=+kv.value;if(!w||!k)return alert('Jaza');D.m.push({w:w,a:a,k:k,mm:+m.value,yy:+y.value});if(a=='mkopo_toka'){f=Math.round(k*0.05);D.m.push({w:w,a:'fomu',k:f,mm:+m.value,yy:+y.value})}kv.value='';S()}function R(){mm=+m.value;yy=+y.value;mi=D.m.filter(x=>x.mm==mm&&x.yy==yy);mp=0;mt=0;mi.forEach(t=>{if(['hisa','ada','marejesho','faini_ada','faini_marejesho','fomu','michango'].includes(t.a))mp+=t.k;if(t.a=='mkopo_toka')mt+=t.k});a.innerText=mp;b.innerText=mt;c.innerText=mp-mt;wl.innerHTML=sw.innerHTML='';if(!D.w.length)wl.innerHTML='<small>Hakuna</small>';D.w.forEach((x,i)=>{wl.innerHTML+=x.j+' <button onclick=\"D.w.splice('+i+',1);S()\" style=width:auto>X</button><br>';sw.innerHTML+='<option>'+x.j+'</option>'})}kvEl=kv;sa.onchange=()=>{k=+kvEl.value;ca.innerHTML=sa.value=='mkopo_toka'&&k>0?'Fomu AUTO='+Math.round(k*0.05)+' (1.5M=75k)':''};kvEl.oninput=()=>sa.onchange();function E(){a1=[['Jina','Ada','Riba']];a2=[['Jina','Mkopo','Fomu','Rejesho','Riba']];a3=[['Jina','Hisa']];a4=[['Jina','Michango']];am={};ar={};dm={};hm={};mc={};D.w.forEach(x=>{am[x.j]=0;ar[x.j]=0;dm[x.j]={c:0,f:0,r:0,fr:0};hm[x.j]=0;mc[x.j]=0});D.m.filter(x=>x.mm==+m.value&&x.yy==+y.value).forEach(t=>{if(t.a=='ada')am[t.w]+=t.k;if(t.a=='faini_ada')ar[t.w]+=t.k;if(t.a=='mkopo_toka')dm[t.w].c+=t.k;if(t.a=='fomu')dm[t.w].f+=t.k;if(t.a=='marejesho')dm[t.w].r+=t.k;if(t.a=='faini_marejesho')dm[t.w].fr+=t.k;if(t.a=='hisa')hm[t.w]+=t.k;if(t.a=='michango')mc[t.w]+=t.k});for(j in am)a1.push([j,am[j],ar[j]]);for(j in dm){d=dm[j];if(d.c>0)a2.push([j,d.c,d.f,d.r,d.fr])}for(j in hm)if(hm[j])a3.push([j,hm[j]]);for(j in mc)if(mc[j])a4.push([j,mc[j]]);wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(a1),'Ada');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(a2),'Mikopo');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(a3),'Hisa');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(a4),'Michango');XLSX.writeFile(wb,'Uwashusema.xlsx')}m.value=11;R();</script>"
